Source: https://github.com/chromedevtools/chrome-devtools-mcp/blob/main/src/BrowserManager.ts

On every MCP connection with --autoConnect, the server reads Chrome's DevToolsActivePort file from the user data directory and connects to the ws endpoint it contains. This file only exists while a running Chrome instance has remote debugging enabled via the chrome://inspect/#remote-debugging checkbox; if it is missing/empty the server errors with instructions to re-enable remote debugging. The MCP server has no code that persists the checkbox setting itself - it depends on Chrome having remote debugging active at connect time.

```typescript
    } else if (channel || userDataDir) {
      if (userDataDir) {
        autoConnect = true;
        // TODO: re-expose this logic via Puppeteer.
        const portPath = path.join(userDataDir, 'DevToolsActivePort');
        try {
          const fileContent = await fs.promises.readFile(portPath, 'utf8');
          const [rawPort, rawPath] = fileContent
            .split('\n')
            .map(line => {
              return line.trim();
            })
            .filter(line => {
              return !!line;
            });
          if (!rawPort || !rawPath) {
            throw new Error(
              `Invalid DevToolsActivePort '${fileContent}' found`,
            );
          }
          const port = parseInt(rawPort, 10);
          if (isNaN(port) || port <= 0 || port > 65535) {
            throw new Error(`Invalid port '${rawPort}' found`);
          }
          const browserWSEndpoint = `ws://127.0.0.1:${port}${rawPath}`;
          connectOptions.browserWSEndpoint = browserWSEndpoint;
        } catch (error) {
          throw new Error(
            `Could not connect to Chrome in ${userDataDir}. Check if Chrome is running and remote debugging is enabled by going to chrome://inspect/#remote-debugging.`,
            {
              cause: error,
            },
          );
